package com.skillbridge;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/catalog")
class CatalogController {
 final WorkspaceService w;final JdbcTemplate db;CatalogController(WorkspaceService w){this.w=w;db=w.db();}
 @GetMapping("/courses") Object courses(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String category,@RequestParam(defaultValue="")String level,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="12")int size){return content("Course",q,category,level,page,size);}
 @GetMapping("/projects") Object projects(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String category,@RequestParam(defaultValue="")String level,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="12")int size){return content("Project",q,category,level,page,size);}
 Object content(String kind,String q,String category,String level,int page,int size){page=Math.max(0,page);size=Math.max(1,Math.min(size,50));String sql=" FROM content WHERE kind=? AND status='Published' AND (title ILIKE ? OR (data->'skills')::text ILIKE ?) AND (?='' OR data->>'category'=?) AND (?='' OR data->>'level'=?)";Object[] params={kind,"%"+q+"%","%"+q+"%",category,category,level,level};Long count=db.queryForObject("SELECT count(*)"+sql,Long.class,params);var args=new ArrayList<Object>(Arrays.asList(params));args.add(size);args.add(page*size);var rows=db.queryForList("SELECT data::text"+sql+" ORDER BY id LIMIT ? OFFSET ?",String.class,args.toArray());return Map.of("items",rows.stream().map(w::object).toList(),"total",count,"page",page,"size",size,"developmentData",true);}
 @GetMapping("/courses/{id}") Object course(@PathVariable int id){return w.content("Course",id);}
 @GetMapping("/projects/{id}") Object project(@PathVariable int id){return w.content("Project",id);}
 @GetMapping("/mentors") Object mentors(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String language,@RequestParam(defaultValue="1000")double maxPrice,@RequestParam(defaultValue="false")boolean available,@RequestParam(defaultValue="0")int page){return db.queryForList("SELECT id,name,expertise,bio,price,language,timezone,development_seed FROM mentor_profile m WHERE approved AND (user_id IS NULL OR EXISTS(SELECT 1 FROM app_user u WHERE u.id=m.user_id AND u.enabled)) AND (name ILIKE ? OR expertise ILIKE ?) AND (?='' OR language=?) AND price<=? AND (NOT ? OR EXISTS(SELECT 1 FROM mentor_slot s WHERE s.mentor_id=m.id AND s.starts_at>now())) ORDER BY id LIMIT 12 OFFSET ?","%"+q+"%","%"+q+"%",language,language,maxPrice,available,Math.max(page,0)*12);}
 @GetMapping("/mentors/{id}/slots") Object slots(@PathVariable long id){return db.query("SELECT starts_at FROM mentor_slot s JOIN mentor_profile m ON m.id=s.mentor_id WHERE m.id=? AND m.approved AND (m.user_id IS NULL OR EXISTS(SELECT 1 FROM app_user u WHERE u.id=m.user_id AND u.enabled)) AND s.starts_at>now() AND NOT EXISTS(SELECT 1 FROM booking b WHERE b.mentor_id=m.id AND b.status='confirmed' AND b.starts_at>s.starts_at-interval '45 minutes' AND b.starts_at<s.starts_at+interval '45 minutes') ORDER BY starts_at LIMIT 50",(r,n)->r.getTimestamp(1).toInstant().toString(),id);}
}
